import{_ as i,a0 as s,w as a,s as u,ao as p,I as e,x as n,a1 as l,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"开源项目领导者可以如何营造包容的环境 | LCTT x X-CMD","titleTemplate":false,"description":"开源项目领导者可以如何营造包容的环境 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开源项目领导者可以如何营造包容的环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开源项目领导者可以如何营造包容的环境 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230210.2 ⭐️⭐️ How open source leaders can foster an inclusive environment","title":"开源项目领导者可以如何营造包容的环境","tag":"202304","desc":""},"relativePath":"202304/20230210.2 ⭐️⭐️ How open source leaders can foster an inclusive environment.md","filePath":"[post].md"}'),d={name:"202304/20230210.2 ⭐️⭐️ How open source leaders can foster an inclusive environment.md"};function m(f,t,x,T,v,b){const r=s("Link");return a(),u("div",null,[t[23]||(t[23]=p('<h1 id="开源项目领导者可以如何营造包容的环境" tabindex="-1">开源项目领导者可以如何营造包容的环境 <a class="header-anchor" href="#开源项目领导者可以如何营造包容的环境" aria-label="Permalink to “开源项目领导者可以如何营造包容的环境”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/22/234237shv6km5mua4tmb3v.jpg" alt=""></p><blockquote><p>那些被你领入社区的人，有一天也会向其他人伸出援手。</p></blockquote><p>开源领导者可以通过创造归属感、提供机会和表示支持来为新来者创造包容性社区。他们了解提交代码和与其他社区成员建立联系的复杂性。创造包容性社区可以建立信誉并获得影响力。这种经验对于想要参与但不知道从哪里开始的贡献者来说是无价的。</p><p>几年前，当我开始管理一个活跃于 Linux 内核社区的团队时，我发现自己因为没有任何内核经验而感到处境困难。复杂的代码库、庞大的电子邮件归档和高风险的交流让我感到害怕。当我团队中的新内核开发人员表达了类似的感受时，我意识到我的感觉在团队里普遍存在。对于那些支持贡献者或想自己做出贡献的人来说，入门的道路并不总是清晰的，甚至可能感觉遥不可及。</p><h3 id="_4-个策略建立包容性领导力" tabindex="-1">4 个策略建立包容性领导力 <a class="header-anchor" href="#_4-个策略建立包容性领导力" aria-label="Permalink to “4 个策略建立包容性领导力”">​</a></h3>',6)),e("p",null,[t[2]||(t[2]=n("开源领导者可以通过为那些希望融入社区的人创造途径来发挥自己的影响力。本文涵盖的策略可应用于正式的 ",-1)),l(r,{href:"https://opensource.com/article/22/8/mentoring-power-multiplier"},{default:o(()=>[...t[0]||(t[0]=[n("指导",-1)])]),_:1}),t[3]||(t[3]=n(" 或 ",-1)),l(r,{href:"https://enterprisersproject.com/article/2021/4/it-leadership-how-to-coach?intcmp=7013a000002qLH8AAM"},{default:o(()=>[...t[1]||(t[1]=[n("辅导",-1)])]),_:1}),t[4]||(t[4]=n(" 关系，但同样适用于日常互动。在培养环境的包容性时，看似微不足道的交流往往会产生最重要的影响。",-1))]),t[24]||(t[24]=e("h4",{id:"怀着好奇心接近了解新人",tabindex:"-1"},[n("怀着好奇心接近了解新人 "),e("a",{class:"header-anchor",href:"#怀着好奇心接近了解新人","aria-label":"Permalink to “怀着好奇心接近了解新人”"},"​")],-1)),t[25]||(t[25]=e("p",null,"经验较少或来自非传统背景的人可能会以意想不到或不同的方式解决问题。在应对这些差异时，如果用妄加评论或批评的方式，可能会在知识曲线通常很陡峭的社区中创造一个不安全的学习环境。例如，Linux 内核的长期贡献者了解社区丰富的历史，这意味着他们不需要明说就能理解社区的决策和反应。新的贡献者必须积累这方面的知识，但只有当他们感到安全，并愿意冒必要的风险来发展自己的技能时，他们才能有效地做到这一点。",-1)),t[26]||(t[26]=e("p",null,"开源领导者可以通过带着好奇心去接近新人来支持他们学习。你可以问他们这样的问题，“你能帮我理解一下你为什么采用这种方法吗？”而不是直接宣布提议的解决方案“对或错”。问题打开了一个继续学习的对话，而不是关闭那些值得探索的重要方面的想法。这个过程也拓宽了领导者的视野，他们可以通过考虑新的观点来学习。",-1)),t[27]||(t[27]=e("h4",{id:"发现并分享学习机会",tabindex:"-1"},[n("发现并分享学习机会 "),e("a",{class:"header-anchor",href:"#发现并分享学习机会","aria-label":"Permalink to “发现并分享学习机会”"},"​")],-1)),t[28]||(t[28]=e("p",null,"开源领导者可以确定适合其他人的项目，使他们可以获得技术专长和学习社区流程。在为他人创造机会的同时，领导者也为自己创造了更多机会。这是因为他们有更多时间探索新的尝试，同时通过分派任务继续推进他们的工作。随着领导者的成长，他们帮助周围的人取得成功的能力变得与他们的直接贡献一样重要。",-1)),e("p",null,[t[6]||(t[6]=n("要知道 ",-1)),l(r,{href:"https://opensource.com/article/20/11/normalize-failure"},{default:o(()=>[...t[5]||(t[5]=[n("失败",-1)])]),_:1}),t[7]||(t[7]=n(" 是学习的一部分，因此你要考虑找一些新手失败后不会造成严重后果的项目。例如，在 Linux 内核中，代码库的某些部分的小改动可能会造成灾难性的后果。考虑可以实现小小的胜利的项目，以帮助新来者在没有高风险的情况下建立信心并感到掌控感。通过会议、电子邮件论坛或任何涉及如何参与到社区里的宣传活动分享这些想法，让人们更容易获取到这些信息。",-1))]),t[29]||(t[29]=e("h4",{id:"展现你脆弱的一面",tabindex:"-1"},[n("展现你脆弱的一面 "),e("a",{class:"header-anchor",href:"#展现你脆弱的一面","aria-label":"Permalink to “展现你脆弱的一面”"},"​")],-1)),t[30]||(t[30]=e("p",null,"拥有更多的经验并不意味着你知道一切。通常情况下，即使是与我共事过的最有经验的 Linux 内核贡献者也会被未知子系统中的新挑战击败。经验不足的社区成员通常会认为经验丰富的社区成员已经了解了一切。但是，经验就是要善于找出你不知道的东西。如果你处于权威地位或者被认为是专家，你可以通过分享个人挣扎和坚持的经验来表现你脆弱的一面，这样做可以鼓励那些和你有着类似感受的人。",-1)),t[31]||(t[31]=e("h4",{id:"为他人做担保",tabindex:"-1"},[n("为他人做担保 "),e("a",{class:"header-anchor",href:"#为他人做担保","aria-label":"Permalink to “为他人做担保”"},"​")],-1)),t[32]||(t[32]=e("p",null,"向你的人脉介绍新来的成员。在激发他们兴趣的领域里，让新成员和在这个领域内具有专业知识的社区成员建立联系。在公共论坛上说出他们的名字，并称赞他们所做的出色工作。作为受人尊敬的领导者，你的支持可以帮助他们在社区内建立联系和信任。",-1)),t[33]||(t[33]=e("p",null,"通过树立社区包容性，我们可以拥有丰富多样的社区。我希望开源领导者会考虑这些建议，因为你提拔到社区的人未来的某天也会同样向别人伸出援手。",-1)),t[34]||(t[34]=e("p",null,[e("em",null,"（题图：MJ:inclusive environment community illustration in high resolution, very detailed）")],-1)),t[35]||(t[35]=e("hr",null,null,-1)),e("p",null,[t[9]||(t[9]=n("via: ",-1)),l(r,{href:"https://opensource.com/article/23/2/open-source-leaders-inclusive-environment"},{default:o(()=>[...t[8]||(t[8]=[n("https://opensource.com/article/23/2/open-source-leaders-inclusive-environment",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=n("作者：",-1)),l(r,{href:"https://opensource.com/users/kcarcia"},{default:o(()=>[...t[10]||(t[10]=[n("Kate Carcia Poulin",-1)])]),_:1}),t[15]||(t[15]=n(" 选题：",-1)),l(r,{href:"https://github.com/lkxed"},{default:o(()=>[...t[11]||(t[11]=[n("lkxed",-1)])]),_:1}),t[16]||(t[16]=n(" 译者：",-1)),l(r,{href:"https://github.com/XiaotingHuang22"},{default:o(()=>[...t[12]||(t[12]=[n("XiaotingHuang22",-1)])]),_:1}),t[17]||(t[17]=n(" 校对：",-1)),l(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[13]||(t[13]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=n("本文由 ",-1)),l(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[n("LCTT",-1)])]),_:1}),t[21]||(t[21]=n(" 原创编译，",-1)),l(r,{href:"https://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[n("Linux中国",-1)])]),_:1}),t[22]||(t[22]=n(" 荣誉推出",-1))])])}const L=i(d,[["render",m]]);export{k as __pageData,L as default};
